import React, {useState} from "react";
import {Dialog, DialogActions, DialogContent, DialogTitle, InputLabel} from "@mui/material";
import {toast} from "react-toastify";
import {
    BulkEditProductCountRequest,
    BulkEditProductCountResult,
    BulkStockUpdateMode,
} from "../../models/product";
import {useTranslation} from "../../i18n";
import {getApiErrorMessage} from "../../api/errors";
import CoreButton from "../../ui/buttons/coreButton";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import CoreTextField from "../../ui/textFields/coreTextField";
import {maximumBulkStockItems} from "./types";

interface BulkStockEditDialogProps {
    open: boolean;
    selectedIds?: number[];
    generationBatchId?: string;
    targetLabel: string;
    onClose: () => void;
    onSubmit: (request: BulkEditProductCountRequest) => Promise<BulkEditProductCountResult>;
}

const BulkStockEditDialog = ({
    open,
    selectedIds,
    generationBatchId,
    targetLabel,
    onClose,
    onSubmit,
}: BulkStockEditDialogProps) => {
    const {t} = useTranslation();
    const [mode, setMode] = useState(BulkStockUpdateMode.Set);
    const [value, setValue] = useState("");
    const [error, setError] = useState("");
    const [isSaving, setIsSaving] = useState(false);
    const selectionLimitExceeded = (selectedIds?.length ?? 0) > maximumBulkStockItems;
    const modeOptions = [
        {id: BulkStockUpdateMode.Set, name: t("Set exact stock quantity")},
        {id: BulkStockUpdateMode.Add, name: t("Add to current stock")},
        {id: BulkStockUpdateMode.Subtract, name: t("Subtract from current stock")},
    ];

    const close = () => {
        if (isSaving) return;
        setValue("");
        setError("");
        onClose();
    };

    const submit = async (event: React.FormEvent) => {
        event.preventDefault();
        if (selectionLimitExceeded) {
            return;
        }

        const numericValue = Number(value);
        if (!Number.isFinite(numericValue) || numericValue < 0 ||
            (mode !== BulkStockUpdateMode.Set && numericValue === 0)) {
            setError(t("Enter a valid non-negative stock quantity."));
            return;
        }

        setIsSaving(true);
        setError("");
        try {
            const result = await onSubmit({
                ids: generationBatchId ? undefined : selectedIds,
                generationBatchId,
                mode,
                value: numericValue,
            });
            toast.success(t("Updated stock items: {count}", {count: result.updated}));
            setValue("");
            onClose();
        } catch (submitError) {
            setError(getApiErrorMessage(submitError, t("Bulk stock editing failed.")));
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <Dialog open={open} onClose={close} fullWidth maxWidth="sm">
            <form onSubmit={submit}>
                <DialogTitle>{t("Bulk stock editing")}</DialogTitle>
                <DialogContent sx={{display: "grid", gap: 2, paddingTop: "10px !important"}}>
                    <div>{targetLabel}</div>
                    <CoreFormControl>
                        <InputLabel>{t("Stock operation")}</InputLabel>
                        <CoreSelect value={mode} label={t("Stock operation")} menuItemProps={modeOptions} onChange={(event: any) => setMode(Number(event.target.value))}/>
                    </CoreFormControl>
                    <CoreTextField fieldArray required type="number" value={value} label={t("Quantity")} onChange={(event: any) => setValue(event.target.value)}/>
                    {selectionLimitExceeded && (
                        <p style={{margin: 0, color: "var(--color-danger)"}}>
                            {t("You can edit no more than 500 stock items at once.")}
                        </p>
                    )}
                    {error && <p style={{margin: 0, color: "var(--color-danger)"}}>{error}</p>}
                </DialogContent>
                <DialogActions>
                    <CoreButton type="button" muiType="secondary" disabled={isSaving} text={t("Cancel")} onClick={close}/>
                    <CoreButton type="submit" muiType="success" disabled={isSaving || selectionLimitExceeded} text={isSaving ? t("Saving...") : t("Apply changes")}/>
                </DialogActions>
            </form>
        </Dialog>
    );
};

export default BulkStockEditDialog;
