import React, {useEffect, useState} from "react";
import {GridRowId, GridRowSelectionModel} from "@mui/x-data-grid";
import {Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, InputLabel} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import TuneIcon from "@mui/icons-material/Tune";
import EditNoteIcon from "@mui/icons-material/EditNote";
import ClearIcon from "@mui/icons-material/Clear";
import styledCom from "styled-components";
import Loader from "../../ui/loader/loader";
import CoreTextField from "../../ui/textFields/coreTextField";
import CoreButton from "../../ui/buttons/coreButton";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import useDebounce from "../../hooks/useDebounce";
import stockColumns from "./stockColumns";
import ProductCountModal from "./productCountModal";
import {useTranslation} from "../../i18n";
import {useGetStockInfoQuery} from "./stockApi";
import {useBulkEditProductCountMutation} from "./stockApi";
import {ProductParams} from "../../models/product";
import {BulkEditProductCountRequest} from "../../models/product";
import {useGetCatalogGenerationBatchesQuery} from "../catalogGeneration/catalogGenerationApi";
import {CategoryType} from "../../models/category";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import BulkStockEditDialog from "./bulkStockEditDialog";

interface GridRow {
    id: GridRowId;
    name: string;
    count: number;
}

const SearchLabel = styledCom.div({
    display: "flex",
    alignItems: "center",
    gap: "8px",
    color: "var(--color-muted)",
    fontSize: "13px",
    fontWeight: 760,
});
const StockFilters = styledCom.div({
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 0.65fr)",
    gap: "14px",
    alignItems: "end",
    "@media (max-width: 760px)": {gridTemplateColumns: "1fr"},
});

const StockManagement = () => {
    const {t, locale} = useTranslation();
    const [productParams, setProductParams] = useState<ProductParams>({
        pageNumber: 1,
        pageSize: 25,
        productCategories: [],
        searchTerm: "",
    });
    const [searchTerm, setSearchTerm] = useState("");
    const debouncedSearch = useDebounce(searchTerm);
    const {data: stockResponse, isLoading, isFetching} = useGetStockInfoQuery(productParams);
    const {data: generationBatches = []} = useGetCatalogGenerationBatchesQuery();
    const [bulkEditProductCount] = useBulkEditProductCountMutation();
    const products = stockResponse?.items || [];
    const metaData = stockResponse?.metaData;
    const [open, setOpen] = useState(false);
    const [row, setRow] = useState<GridRow>();
    const [paginationModel, setPaginationModel] = useState({
        pageSize: productParams.pageSize,
        page: productParams.pageNumber - 1,
    });
    const [selectedIds, setSelectedIds] = useState<GridRowSelectionModel>([]);
    const [bulkTarget, setBulkTarget] = useState<"selection" | "batch" | null>(null);
    const productBatchOptions = [
        {id: "", name: t("All generation batches")},
        ...generationBatches
            .filter((batch) => batch.itemType === CategoryType.Product)
            .map((batch) => ({id: batch.id, name: batch.name})),
    ];
    const selectedBatch = generationBatches.find((batch) => batch.id === productParams.generationBatchId);

    const handleClose = () => {
        setOpen(false);
    };

    const handleOpen = (row: GridRow) => {
        setRow(row);
        setOpen(true);
    };

    useEffect(() => {
        setProductParams((current) => ({
            ...current,
            searchTerm: debouncedSearch,
            pageNumber: 1,
        }));
        setPaginationModel((current) => ({...current, page: 0}));
    }, [debouncedSearch]);

    const pageChangeHandler = (e: any) => {
        setProductParams((current) => ({
            ...current,
            pageNumber: e.page + 1,
            pageSize: e.pageSize,
        }));
        setPaginationModel(e);
    };

    const bulkEditHandler = async (request: BulkEditProductCountRequest) => {
        const result = await bulkEditProductCount(request).unwrap();
        setSelectedIds([]);
        setBulkTarget(null);
        return result;
    };

    if (isLoading) {
        return <Loader/>;
    }

    return (
        <MainDiv>
            <BulkStockEditDialog
                open={bulkTarget !== null}
                selectedIds={bulkTarget === "selection" ? selectedIds.map(Number) : undefined}
                generationBatchId={bulkTarget === "batch" ? productParams.generationBatchId : undefined}
                targetLabel={bulkTarget === "batch"
                    ? t("Entire generation batch: {name}", {name: selectedBatch?.name ?? ""})
                    : t("Selected products: {count}", {count: selectedIds.length})}
                onClose={() => setBulkTarget(null)}
                onSubmit={bulkEditHandler}
            />
            <Dialog
                open={open}
                onClose={() => handleClose()}
            >
                <DialogTitle>{t("Изменение остатков на складе")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("Внесите актуальное количество товара на складе.")}
                    </DialogContentText>
                    <ProductCountModal
                        id={row?.id!}
                        name={row?.name!}
                        count={row?.count!}
                        handleClose={handleClose}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => handleClose()}>{t("Отмена")}</Button>
                </DialogActions>
            </Dialog>

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Склад")}</PageTitle>
                    <PageSubtitle>
                        {t("Остатки товаров, контроль наличия и быстрое обновление количества.")}
                    </PageSubtitle>
                </PageTitleGroup>
            </PageHeader>

            <Surface>
                <Toolbar>
                    <SearchLabel>
                        <SearchIcon fontSize="small"/>
                        {t("Поиск по складу")}
                    </SearchLabel>
                    <ToolbarActions>
                        {selectedIds.length > 0 && (
                            <CoreButton text={t("Clear selection")} leftIcon={<ClearIcon/>} muiType="secondary" onClick={() => setSelectedIds([])}/>
                        )}
                        <CoreButton
                            text={t("Edit selected stock ({count})", {count: selectedIds.length})}
                            leftIcon={<EditNoteIcon/>}
                            muiType="edit"
                            disabled={selectedIds.length === 0}
                            onClick={() => setBulkTarget("selection")}
                        />
                        {productParams.generationBatchId && (
                            <CoreButton
                                text={t("Edit entire batch stock")}
                                leftIcon={<TuneIcon/>}
                                muiType="success"
                                onClick={() => setBulkTarget("batch")}
                            />
                        )}
                    </ToolbarActions>
                </Toolbar>
                <StockFilters>
                    <CoreTextField
                        verticalMargin
                        value={searchTerm || ""}
                        label={t("Название товара или описание...")}
                        onChange={(e: any) => setSearchTerm(e.target.value)}
                    />
                    <CoreFormControl>
                        <InputLabel>{t("Generation batch")}</InputLabel>
                        <CoreSelect
                            required={false}
                            value={productParams.generationBatchId ?? ""}
                            label={t("Generation batch")}
                            menuItemProps={productBatchOptions}
                            onChange={(event: any) => {
                                const generationBatchId = String(event.target.value) || undefined;
                                setProductParams((current) => ({...current, generationBatchId, pageNumber: 1}));
                                setPaginationModel((current) => ({...current, page: 0}));
                                setSelectedIds([]);
                            }}
                        />
                    </CoreFormControl>
                </StockFilters>
                <StyledDataGrid
                    loading={isFetching}
                    pagination
                    paginationMode="server"
                    rowCount={metaData?.totalCount || 0}
                    autoHeight
                    rows={products}
                    columns={stockColumns(handleOpen, t, locale)}
                    paginationModel={paginationModel}
                    onPaginationModelChange={(e) => pageChangeHandler(e)}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                    checkboxSelection
                    keepNonExistentRowsSelected
                    rowSelectionModel={selectedIds}
                    onRowSelectionModelChange={setSelectedIds}
                />
            </Surface>
        </MainDiv>
    );
};

export default StockManagement;
