import React, {useState} from "react";
import styledCom from "styled-components";
import {GridRowId} from "@mui/x-data-grid";
import CoreButton from "../../ui/buttons/coreButton";
import CoreTextField from "../../ui/textFields/coreTextField";
import {ISetProductForStock} from "../../models/product";
import {useTranslation} from "../../i18n";
import {useEditProductCountMutation} from "./stockApi";
import {toast} from "react-toastify";

interface IProps {
    id: GridRowId;
    name: string;
    count: number;
    handleClose: any;
}

const ModalForm = styledCom.form({
    display: "grid",
    gap: "10px",
    marginTop: "12px",
});

const ProductCountModal = ({id, name, count, handleClose}: IProps) => {
    const {t} = useTranslation();
    const [newCount, setNewCount] = useState(count);
    const [editProductCount, {isLoading}] = useEditProductCountMutation();

    const handleSubmit = async (e: any) => {
        e.preventDefault();

        if (id) {
            const productCount: ISetProductForStock = {count: newCount, id};
            try {
                await editProductCount(productCount).unwrap();
                toast.success(t("Остаток продукта зафиксирован"));
                handleClose();
            } catch {
                toast.error(t("Ошибка управления складом"));
            }
        }
    };

    return (
        <ModalForm onSubmit={(event: React.FormEvent<HTMLFormElement>) => handleSubmit(event)}>
            <CoreTextField
                disabled
                value={name}
                label={t("Название")}
            />
            <CoreTextField
                value={newCount}
                type="number"
                label={t("Количество")}
                required
                onChange={(e: any) => setNewCount(Number(e.target.value))}
            />
            <CoreButton
                fullWidth
                text={t("Сохранить")}
                muiType="success"
                type="submit"
                disabled={isLoading}
            />
        </ModalForm>
    );
};

export default ProductCountModal;
