import {GridActionsCellItem, GridColDef, GridRowParams} from "@mui/x-data-grid";
import EditTwoToneIcon from "@mui/icons-material/EditTwoTone";
import React from "react";
import {Avatar, Link} from "@mui/material";
import {Link as RouterLink} from "react-router-dom";
import {Translate} from "../../i18n";

const stockColumns = (handleOpen: (row: any) => void, t: Translate, locale = "ru-RU"): GridColDef[] => [
    {
        field: "imageName",
        align: "center",
        headerName: "",
        width: 64,
        renderCell: (params) => (
            <Avatar
                sx={{width: 36, height: 36, borderRadius: "10px"}}
                variant="rounded"
                src={params.value}
                alt={params.row.name}
            />
        ),
    },
    {
        field: "name",
        headerName: t("Название"),
        minWidth: 260,
        flex: 1,
        renderCell: params => <Link component={RouterLink} to={`/productsManagement/editProduct/productDetails/${params.id}`} sx={{fontWeight: 650}}>{params.value}</Link>,
    },
    {
        field: "price",
        headerName: t("Цена, BYN"),
        type: "number",
        align: "center",
        width: 120,
        renderCell: params => <strong>{Number(params.value) > 0 ? Number(params.value).toLocaleString(locale, {minimumFractionDigits: 2, maximumFractionDigits: 2}) : "Не указана"}</strong>,
    },
    {
        field: "category",
        headerName: t("Категория"),
        sortable: true,
        minWidth: 150,
        flex: 0.7,
    },
    {
        field: "count",
        headerName: t("Остаток, шт."),
        sortable: true,
        align: "center",
        width: 130,
    },
    {
        field: "Edit",
        headerName: t("Изменить"),
        type: "actions",
        width: 104,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={<EditTwoToneIcon/>}
                label={t("Изменить остаток")}
                onClick={() => handleOpen(params.row)}
            />,
        ],
    },
];

export default stockColumns;
