import {GridRowId} from "@mui/x-data-grid";
import {ICategory} from "./category";

export interface IProduct {
    id: number
    name: string
    gtin: string
    imageName?: string
    hasCustomImage?: boolean
    description: string | null
    price: number
    purchasePrice?: number | null
    costPrice?: number | null
    markupPercent?: number | null
    requiresPriceApproval?: boolean
    pricingVersionId?: string | null
    pricingEffectiveFrom?: string | null
    category?: ICategory
    categoryId: number
    categoryName?: string
    characteristics: IProductCharacteristic[]
    fields: Record<string, string>
}

export interface IShortProduct {
    id: number
    name: string
    gtin: string
    imageName?: string
    price: number;
    purchasePrice?: number | null;
    costPrice?: number | null;
    markupPercent?: number | null;
    requiresPriceApproval?: boolean;
    category?: string;
    count?: number;
}

export interface ICreateOrEditProduct {
    id?: string,
    name: string,
    gtin: string,
    imageName?: string,
    description: string | null,
    price: number,
    categoryId: string | number,
    characteristics: IProductCharacteristic[],
    fields: Record<string, string>
}

export interface ProductParams {
    searchTerm?: string;
    productCategories?: string[];
    categories?: string;
    generationBatchId?: string;
    pageSize: number;
    pageNumber: number;
}

export enum BulkStockUpdateMode {
    Set = 0,
    Add = 1,
    Subtract = 2,
}

export interface BulkEditProductCountRequest {
    ids?: number[];
    generationBatchId?: string;
    mode: BulkStockUpdateMode;
    value: number;
}

export interface BulkEditProductCountResult {
    updated: number;
}

export interface ISetProductForStock {
    id: string | GridRowId,
    count: number,
}

export interface IProductCharacteristic {
    name: string;
    value: string;
}
